                      "</u:%sResponse>",
                 action, ns, timeout, action) < 0) {
        upnphttp_send_error(h, 500, "Failed to build response");
        return;
    }

    upnphttp_send_response(h, 200, response);
    free(response);
}

void handle_outbound_pinhole_timeout(struct upnphttp *h, const char *action, const char *ns) {
    char *internal_client_ip = NULL;
    int internal_port = 0;
    char *remote_host = NULL;
    int remote_port = 0;
    char *protocol = NULL;
    int timeout = 0;

    if (!ipv6_forwarding_enabled()) {
        upnphttp_SendAction(h, ns, action, NULL, 0, "InvalidArgument", "IPv6 forwarding is disabled.");
        return;
    }

    if (!upnphttp_GetRequestArgument(h, "NewInternalClient", "%ms", &internal_client_ip) ||
        !upnphttp_GetRequestArgument(h, "NewInternalPort", "%d", &internal_port) ||
        !upnphttp_GetRequestArgument(h, "NewRemoteHost", "%ms", &remote_host) ||
        !upnphttp_GetRequestArgument(h, "NewRemotePort", "%d", &remote_port) ||
        !upnphttp_GetRequestArgument(h, "NewProtocol", "%ms", &protocol)) {
        upnphttp_SendAction(h, ns, action, NULL, 0, "InvalidArgument", "Required arguments missing.");
        return;
    }

    if (strcasecmp(protocol, "TCP") != 0 && strcasecmp(protocol, "UDP") != 0) {
        upnphttp_SendAction(h, ns, action, NULL, 0, "InvalidArgument", "Unsupported protocol.");
        return;
    }

    timeout = check_outbound_pinhole_timeout(internal_client_ip, internal_port,
                                             remote_host, remote_port, protocol);

    if (timeout < 0) {
        upnphttp_SendAction(h, ns, action, NULL, 0, "ActionFailed", "Failed to retrieve timeout.");
        return;
    }

    char soap_response[256];
    snprintf(soap_response, sizeof(soap_response),
             "<u:%sResponse xmlns:u=\"%s\">"
             "<NewTimeout>%d</NewTimeout>"
             "</u:%sResponse>",
             action, ns, timeout, action);

    upnphttp_SendAction(h, ns, action, soap_response, strlen(soap_response), NULL, NULL);
}

